#!/usr/bin/env python3
"""Copy prototype/timeline.css (the single source of the styles) into the component packages.

    python3 tools/sync_css.py

web-component/src/timeline.css.js   the stylesheet as a JS string (the element needs no bundler)
react/src/timeline.css              the same file, imported by the React component
Do not edit the copies: they are overwritten.
"""
import json, pathlib

root = pathlib.Path(__file__).resolve().parent.parent
css = (root / 'prototype' / 'timeline.css').read_text()

(root / 'web-component' / 'src' / 'timeline.css.js').write_text(
    '// Generated by tools/sync_css.py from prototype/timeline.css. Do not edit.\n'
    'export default ' + json.dumps(css) + ';\n')
(root / 'react' / 'src' / 'timeline.css').write_text(css)
print('synced timeline.css into web-component/src and react/src')

# A classic-script build of all the elements (no ES modules), so the demo pages also work from file://.
import re
src = root / 'web-component' / 'src'
ORDER = ['timeline.css.js', 'util.js', 'data.js', 'view-element.js', 'outline-list.js', 'outline-table.js',
         'timeline-rail.js', 'view-switcher.js']
def body(name):
    t = (src / name).read_text()
    t = re.sub(r"^import .*?;[ \t]*\n", "", t, flags=re.M)
    t = t.replace('export default ', 'const baseCss = ', 1) if name == 'timeline.css.js' else t
    return re.sub(r"^export (const|function|class|let) ", r"\1 ", t, flags=re.M)
bundle = (root / 'web-component' / 'components.bundle.js')
bundle.write_text(
    '// Generated by tools/sync_css.py from web-component/src. Do not edit. A classic script: it defines the elements\n'
    '// and window.TimelineKit = { TimelineRail, OutlineList, OutlineTable, ViewSwitcher, ViewElement, h, readModel, flatten }.\n'
    '( function () {\n' + '\n'.join(body(n) for n in ORDER)
    + '\nwindow.TimelineKit = { TimelineRail, OutlineList, OutlineTable, ViewSwitcher, ViewElement, h, readModel, flatten };\n} )();\n')
print('wrote web-component/components.bundle.js')
